    ManyToMany
}

public class RelationshipMap
{
    private Dictionary<Type, Dictionary<Type, RelationshipType>> relationships;

    public RelationshipMap()
    {
        relationships = new Dictionary<Type, Dictionary<Type, RelationshipType>>();
    }

    public void AddRelationship(Type entityType1, Type entityType2, RelationshipType relationshipType)
    {
        if (!relationships.ContainsKey(entityType1))
        {
            relationships[entityType1] = new Dictionary<Type, RelationshipType>();
        }
        relationships[entityType1][entityType2] = relationshipType;

        if (!relationships.ContainsKey(entityType2))
        {
            relationships[entityType2] = new Dictionary<Type, RelationshipType>();
        }
        relationships[entityType2][entityType1] = relationshipType;
    }

    public IEnumerable<Type> GetRelatedEntities(Type entityType, RelationshipType relationshipType)
    {
        if (relationships.ContainsKey(entityType))
        {
            return relationships[entityType].Where(r => r.Value == relationshipType).Select(r => r.Key);
        }
        return new List<Type>();
    }
}
